/bin/bash -lc "python3 -c \"
from PIL import Image
import numpy as np
a = np.array(Image.open('first_frame.png')).astype(int)
lum=a.mean(axis=2)
chroma = np.max(a,axis=2)-np.min(a,axis=2)
# left light pillow surface: scan down, find first y where lum>115 and stays-ish bright for 6 of next 8
def surf_bright(x):
    for y in range(20,120):
        if lum[y,x]>115 and np.mean(lum[y:y+8,x]>110)>=0.75 and chroma[y,x]<=25:
            return y
    return -1
def surf_dark(x):
    # dark pillow ~ lum 70..115, background behind (above) is dark bg lum<40 or grabber
    for y in range(30,120):
        if 60<lum[y,x]<120 and np.mean((lum[y:y+8,x]>60)&(lum[y:y+8,x]<125))>=0.75 and chroma[y,x]<=25:
            return y
    return -1
print('left pillow surface:')
for x in range(20,190,6): print(x, surf_bright(x))
print('right pillow surface:')
for x in range(195,256,4): print(x, surf_dark(x))
\""
